<script setup>
import { onMounted, reactive } from 'vue';import { listInvoices } from '../../api/billing';import { session } from '../../utils/session';import { money,text,formatDate,tagType } from '../../utils/enums';import PageHeader from '../../components/PageHeader.vue';import AppPagination from '../../components/AppPagination.vue'
const path=session.user.role==='CLIENT'?'/client/invoices':'/admin/invoices';const state=reactive({list:[],total:0,pageNum:1,pageSize:10,loading:false});const load=async()=>{state.loading=true;try{const r=await listInvoices(path,state);state.list=r.data.list;state.total=r.data.total}finally{state.loading=false}};onMounted(load)
</script>
<template><div class="page"><PageHeader title="发票记录" description="查看账单对应的模拟发票记录"/><div class="table-wrap"><el-table v-loading="state.loading" :data="state.list"><el-table-column prop="invoiceNo" label="发票号码" min-width="200"/><el-table-column prop="invoiceTitle" label="发票抬头" min-width="180"/><el-table-column prop="invoiceType" label="类型" width="100"/><el-table-column label="金额" width="110"><template #default="{row}">{{money(row.amount)}}</template></el-table-column><el-table-column label="状态" width="100"><template #default="{row}"><el-tag :type="tagType(row.status)">{{text('invoiceStatus',row.status)}}</el-tag></template></el-table-column><el-table-column label="开具时间" width="160"><template #default="{row}">{{formatDate(row.issueTime)}}</template></el-table-column></el-table></div><AppPagination v-model:page="state.pageNum" v-model:size="state.pageSize" :total="state.total" @change="load"/></div></template>
